package com. topdon. menu. view import android. content. Context import android. util. AttributeSet import android. view. LayoutInflater import android. view. MotionEvent import android. view. View import android. view. ViewGroup import android. widget. FrameLayout import androidx. core. view. isVisible import androidx. recyclerview. widget. RecyclerView import androidx. viewpager2. widget. ViewPager2 import com. bumptech. glide. Glide import com. bumptech. glide. load. MultiTransformation import com. bumptech. glide. load. resource. bitmap. CenterCrop import com. bumptech. glide. request. RequestOptions import com. topdon. menu. R as MenuR import com. topdon. lib. core. R import com. topdon. menu. databinding. ViewCameraMenuBinding / *  *  * Menu 1 - Photo capture and video recording functionality wrapper. *  * The central photo capture/recording button has the following states: * - Photo capture mode - Normal * - Photo capture mode - Capturing - Immediate capture * - Photo capture mode - Capturing - Delayed capture * - Recording mode - Normal * - Recording mode - Recording in progress *  * Created by LCG on 2024/11/8. * / class CameraMenuView: FrameLayout, View. OnClickListener { companion object { / *  * onCameraClickListener event code: Photo capture/recording *  * / const val CODE_ACTION = 0 / *  * onCameraClickListener event code: Gallery *  * / const val CODE_GALLERY = 1 / *  * onCameraClickListener event code: More menu *  * / const val CODE_MORE = 2 / *  * onCameraClickListener event code: Switch to photo capture *  * / const val CODE_TO_PHOTO = 3 / *  * onCameraClickListener event code: Switch to video recording *  * / const val CODE_TO_VIDEO = 4 } / *  *  * Whether currently in video recording mode. *  * true - video recording mode, false - photo capture mode * / var isVideoMode: Boolean get () = binding. viewPager2. currentItem == 1 set (value) { binding. viewPager2. currentItem = if (value) 1 else 0 } / *  *  * Photo capture/recording text visibility and switching control, switching not allowed during photo capture or video recording. *  * true-visible and switchable false-hidden and not switchable * / var canSwitchMode: Boolean get () = binding. viewPager2. isUserInputEnabled set (value) { binding. viewPager2. isUserInputEnabled = value binding. tvPhoto. isVisible = value binding. tvVideo. isVisible = value } / *  *  * Click event listener for each operation. * actionCode: 0-Photo capture/recording 1-gallery 2-more menu 3-switch to photo capture 4-switch to video recording * / var onCameraClickListener: ( (actionCode: Int) -> Unit) ? = null / *  *  * Set the middle photo capture/recording button to normal state (not capturing/not recording) * / fun setToNormal () { if (isVideoMode) { binding. ivAction. setImageResource (MenuR. drawable. svg_camera_video_normal) } else { binding. ivAction. setImageResource (MenuR. drawable. svg_camera_photo_normal) } } / *  *  * Set the middle photo capture/recording button to active recording state - photo capture in progress/delayed photo capture/video recording in progress * @param isDelay true-delayed photo capture false-immediate photo capture or video recording * / fun setToRecord (isDelay: Boolean) { if (isVideoMode) { binding. ivAction. setImageResource (MenuR. drawable. svg_camera_video_record) } else { if (isDelay) { binding. ivAction. setImageResource (MenuR. drawable. svg_camera_photo_record_delay) } else { binding. ivAction. setImageResource (MenuR. drawable. svg_camera_photo_record_at_once) } } } / *  *  * Set gallery cover image. * / fun refreshGallery (path: String) { try { Glide. with (this) . load (path) . apply (RequestOptions. bitmapTransform (MultiTransformation (CenterCrop () ) ) . placeholder (MenuR. drawable. shape_oval_33) . error (MenuR. drawable. shape_oval_33) ) . into (binding. ivGallery) } catch (_: Exception) { } } private lateinit var binding: ViewCameraMenuBinding constructor (context: Context) : this (context, null) constructor (context: Context, attrs: AttributeSet?) : this (context, attrs, 0) constructor (context: Context, attrs: AttributeSet?, defStyleAttr: Int) : this (context, attrs, defStyleAttr, 0) constructor (context: Context, attrs: AttributeSet?, defStyleAttr: Int, defStyleRes: Int) : super (context, attrs, defStyleAttr, defStyleRes) { if (isInEditMode) { LayoutInflater. from (context) . inflate (MenuR. layout. view_camera_menu, this, true) } else { binding = ViewCameraMenuBinding. inflate (LayoutInflater. from (context) , this, true) binding. viewPager2. adapter = MenuCameraAdapter () binding. viewPager2. registerOnPageChangeCallback (MyOnPageChangeCallback () ) binding. ivAction. setOnClickListener (this) binding. ivGallery. setOnClickListener (this) binding. ivMore. setOnClickListener (this) binding. tvPhoto. setOnClickListener (this) binding. tvVideo. setOnClickListener (this) } } override fun dispatchTouchEvent (ev: MotionEvent?) : Boolean { binding. viewPager2. dispatchTouchEvent (ev) return super. dispatchTouchEvent (ev) } / *  *  * Long press photo capture or video recording to show or hide overlay points for photo capture and recording. * / private var lastClickTime: Long = 0 override fun onClick (v: View?) { when (v) { binding. ivAction -> { // startPhoto capture/startrecording/stoprecording val currentTime = System. currentTimeMillis () if (currentTime - lastClickTime > 500) { lastClickTime = currentTime onCameraClickListener?. invoke (CODE_ACTION) } } binding. ivGallery -> { // gallery onCameraClickListener?. invoke (CODE_GALLERY) } binding. ivMore -> { // moremenu onCameraClickListener?. invoke (CODE_MORE) } binding. tvPhoto -> { // Photo capturetext binding. viewPager2. currentItem = 0 } binding. tvVideo -> { // Video mode text binding. viewPager2. currentItem = 1 } } } inner class MyOnPageChangeCallback: ViewPager2. OnPageChangeCallback () { override fun onPageScrolled (position: Int, positionOffset: Float, positionOffsetPixels: Int) { val scrollWidth: Float = binding. tvPhoto. width / 2f + binding. tvVideo. width / 2f if (position == 0) { binding. tvPhoto. translationX = -scrollWidth * positionOffset binding. tvVideo. translationX = -scrollWidth * positionOffset } else { binding. tvPhoto. translationX = -scrollWidth binding. tvVideo. translationX = -scrollWidth } } override fun onPageSelected (position: Int) { binding. tvPhoto. isSelected = position == 0 binding. tvVideo. isSelected = position == 1 binding. ivAction. setImageResource (if (position == 1) MenuR. drawable. svg_camera_video_normal else MenuR. drawable. svg_camera_photo_normal) onCameraClickListener?. invoke (if (position == 1) CODE_TO_VIDEO else CODE_TO_PHOTO) } } / *  *  * ViewPager2 used by Adapter. * / class MenuCameraAdapter: RecyclerView. Adapter<MenuCameraAdapter. ViewHolder> () { override fun onCreateViewHolder (parent: ViewGroup, viewType: Int) : ViewHolder { val view = View (parent. context) view. layoutParams = ViewGroup. LayoutParams (ViewGroup. LayoutParams. MATCH_PARENT, ViewGroup. LayoutParams. MATCH_PARENT) return ViewHolder (view) } override fun onBindViewHolder (holder: ViewHolder, position: Int) { } override fun getItemCount () : Int = 2 class ViewHolder (rootView: View) : RecyclerView. ViewHolder (rootView) } }